function defaultBaziLiunian(startYear, count) {
    const gan = ["甲", "乙", "丙", "丁", "戊", "己", "庚", "辛", "壬", "癸"];
    const zhi = ["子", "丑", "寅", "卯", "辰", "巳", "午", "未", "申", "酉", "戌", "亥"];
    const out = [];
    for (let i = 0; i < count; i += 1) {
        const year = startYear + i;
        out.push({
            year,
            gan: gan[((year - 4) % 10 + 10) % 10],
            zhi: zhi[((year - 4) % 12 + 12) % 12],
        });
    }
    return out;
}
